code.snippet:
body.t-terminal .tagline::before { content: "$ whoami → "; color: var(--text-2); font-weight: 400; }
body.t-terminal .section-title::before { content: "# "; color: var(--text-2); }
body.t-terminal .section-tag::before { content: "~/"; color: var(--text-2); }
body.t-terminal .hero-badge i { border-radius: 0; animation: blink 1.1s steps(2) infinite; }
@keyframes blink { 50% { opacity: .15; box-shadow: none; } }
body.t-terminal .card.featured::before { content: "$ TOP"; font-family: var(--font-body); }
body.t-terminal .logo::after { content: "▊"; color: var(--accent); animation: blink 1.1s steps(2) infinite; margin-left: 4px; }
